using System;
int[,] orders = { { 2, 5, 1 }, { 4, 1, 3 } };
int grand = 0;
for (int r = 0; r < orders.GetLength(0); r++) {
    int rowTotal = 0;
    for (int c = 0; c < orders.GetLength(1); c++) rowTotal += orders[r, c];
    grand += rowTotal;
    Console.WriteLine($"Row {r}: {rowTotal}");
}
Console.WriteLine($"Grand: {grand}");

